// Normalise the webhook body and reject inquiries without a name or a usable email.
const body = $input.first().json.body ?? {};
const clean = (value) => String(value ?? '').trim();

const inquiry = {
  name: clean(body.name),
  email: clean(body.email).toLowerCase(),
  phone: clean(body.phone),
  message: clean(body.message),
  source: clean(body.source) || 'website',
};

const errors = [];
if (!inquiry.name) errors.push('name is required');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(inquiry.email)) errors.push('a valid email is required');
if (inquiry.message.length > 5000) errors.push('message must be 5000 characters or fewer');

return [{ json: { valid: errors.length === 0, errors, inquiry } }];

// Store the inquiry in workflow static data and build the instant reply.
// Static data only persists for production (active workflow) executions, not manual test runs.
const store = $getWorkflowStaticData('global');
store.inquiries = store.inquiries ?? {};

const business = $env.BUSINESS_NAME || 'Example Plumbing Co.';
const { inquiry } = $input.first().json;
const id = `inq_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;

const record = {
  id,
  ...inquiry,
  receivedAt: new Date().toISOString(),
  status: 'open',
  followUps: {},
};
store.inquiries[id] = record;

const notification = {
  channel: 'email',
  recipient: record.email,
  subject: `Thanks for contacting ${business}`,
  body: [
    `Hi ${record.name},`,
    '',
    'Thanks for reaching out. We have your message and will reply within one business day.',
    '',
    `The ${business} team`,
  ].join('\n'),
  metadata: { inquiryId: id, kind: 'instant_reply' },
};

return [{ json: { record, notification } }];

// Mark an inquiry as replied or closed so no further follow-ups are sent.
const store = $getWorkflowStaticData('global');
const { id, status } = $input.first().json.body ?? {};
const allowed = ['open', 'replied', 'closed'];
const record = store.inquiries?.[id];

if (!record) {
  return [{ json: { ok: false, code: 404, error: 'unknown inquiry id' } }];
}
if (!allowed.includes(status)) {
  return [{ json: { ok: false, code: 400, error: `status must be one of: ${allowed.join(', ')}` } }];
}

record.status = status;
record.updatedAt = new Date().toISOString();
return [{ json: { ok: true, code: 200, record } }];

// Find open inquiries whose day 1, 3 or 7 follow-up is due.
// If the workflow was paused and several are overdue, only the latest one is sent
// and the older ones are marked as skipped, so a lead never gets a burst of emails.
const FOLLOW_UP_DAYS = [1, 3, 7];
const DAY_MS = 24 * 60 * 60 * 1000;

const store = $getWorkflowStaticData('global');
const business = $env.BUSINESS_NAME || 'Example Plumbing Co.';
const now = Date.now();

const templates = {
  1: {
    subject: `Following up on your request to ${business}`,
    body: (name) => `Hi ${name},\n\nJust checking in on your request from yesterday. Reply to this email with a good time to call and we will get you booked in.\n\nThe ${business} team`,
  },
  3: {
    subject: `Still need a hand? ${business}`,
    body: (name) => `Hi ${name},\n\nWe have not heard back yet, so here is a reminder that we have openings this week. Reply any time and we will take it from there.\n\nThe ${business} team`,
  },
  7: {
    subject: `Last check-in from ${business}`,
    body: (name) => `Hi ${name},\n\nThis is our last follow-up. If you still need help, just reply and we will pick it up straight away.\n\nThe ${business} team`,
  },
};

const due = [];
for (const record of Object.values(store.inquiries ?? {})) {
  if (record.status !== 'open') continue;

  const age = now - Date.parse(record.receivedAt);
  const dueDays = FOLLOW_UP_DAYS.filter((day) => age >= day * DAY_MS && !record.followUps[day]);
  if (dueDays.length === 0) continue;

  const day = dueDays[dueDays.length - 1];
  for (const older of dueDays.slice(0, -1)) record.followUps[older] = 'skipped';

  due.push({
    json: {
      channel: 'email',
      recipient: record.email,
      subject: templates[day].subject,
      body: templates[day].body(record.name),
      metadata: { inquiryId: record.id, kind: 'follow_up', day },
    },
  });
}

return due;

// Record which follow-ups were sent. The notification API echoes back the
// metadata it was given, which tells us the inquiry id and follow-up day.
const store = $getWorkflowStaticData('global');
const sentAt = new Date().toISOString();

for (const item of $input.all()) {
  const { inquiryId, day } = item.json.metadata ?? {};
  const record = store.inquiries?.[inquiryId];
  if (record && day) record.followUps[day] = sentAt;
}

return $input.all();
